-- VERIFICATION
SELECT 'branches' AS [Table], COUNT(*) AS [Rows] FROM branches
UNION ALL SELECT 'employees', COUNT(*) FROM employees
UNION ALL SELECT 'customers', COUNT(*) FROM customers
UNION ALL SELECT 'account_types', COUNT(*) FROM account_types
UNION ALL SELECT 'account_statuses', COUNT(*) FROM account_statuses
UNION ALL SELECT 'accounts', COUNT(*) FROM accounts
UNION ALL SELECT 'transaction_types', COUNT(*) FROM transaction_types
UNION ALL SELECT 'transactions', COUNT(*) FROM transactions
UNION ALL SELECT 'services', COUNT(*) FROM services
UNION ALL SELECT 'customer_services', COUNT(*) FROM customer_services
UNION ALL SELECT 'loans', COUNT(*) FROM loans
UNION ALL SELECT 'loan_payments', COUNT(*) FROM loan_payments
UNION ALL SELECT 'cards', COUNT(*) FROM cards
UNION ALL SELECT 'beneficiaries', COUNT(*) FROM beneficiaries
UNION ALL SELECT 'deposits', COUNT(*) FROM deposits
UNION ALL SELECT 'audit_log', COUNT(*) FROM audit_log
ORDER BY [Rows] DESC;
